#include <iostream>

class DeviceMonitor {
public:
    DeviceMonitor(int id, int voltageLevel)
        : deviceId(id), voltage(voltageLevel) {}

    // Hàm truy cập vị từ (predicate function): kiểm tra trạng thái an toàn
    bool isOperational() const {
        return validateVoltage(); // Ủy quyền kiểm tra cho hàm tiện ích
    }

    void displayStatus() const {
        std::cout << "Device [" << deviceId << "] - Operational: "
                  << (isOperational() ? "YES" : "NO") << "\n";
    }

private:
    int deviceId;
    int voltage;

    // Hàm tiện ích/hỗ trợ (utility/helper function): đặt private để hỗ trợ nội bộ
    bool validateVoltage() const {
        return (voltage >= 200 && voltage <= 240);
    }
};

int main() {
    DeviceMonitor dev1(101, 220); // Tạo đối tượng trực tiếp
    DeviceMonitor& ref1 = dev1;   // Tham chiếu đến đối tượng
    DeviceMonitor* ptr1 = &dev1;  // Con trỏ tới đối tượng

    // 1. Truy cập qua toán tử chấm (.) trên tên đối tượng và tham chiếu
    dev1.displayStatus();
    ref1.displayStatus();

    // 2. Truy cập qua toán tử mũi tên (->) trên con trỏ
    ptr1->displayStatus();

    // Tạo đối tượng điện áp không hợp lệ
    DeviceMonitor dev2(102, 180);
    DeviceMonitor* ptr2 = &dev2;
    ptr2->displayStatus();

    return 0;
}

#include <iostream>

// Mô phỏng nội dung tệp tiêu đề Time.h với include guard chuẩn
#ifndef TIME_H
#define TIME_H

class Time {
public:
    Time(); // Constructor
    void setTime(int h, int m, int s);
    void printUniversal() const; // Hàm const: cam kết không thay đổi trạng thái đối tượng
    void printStandard() const;  // Hàm const

private:
    unsigned int hour{0};   // 0 - 23 (định dạng 24 giờ)
    unsigned int minute{0}; // 0 - 59
    unsigned int second{0}; // 0 - 59
};

#endif // TIME_H

// Triển khai tối giản các hàm const để kiểm chứng cơ chế biên dịch
Time::Time() : hour(0), minute(0), second(0) {}

void Time::setTime(int h, int m, int s) {
    if (h >= 0 && h < 24 && m >= 0 && m < 60 && s >= 0 && s < 60) {
        hour = h;
        minute = m;
        second = s;
    }
}

void Time::printUniversal() const {
    std::cout << (hour < 10 ? "0" : "") << hour << ":"
              << (minute < 10 ? "0" : "") << minute << ":"
              << (second < 10 ? "0" : "") << second << "\n";
}

void Time::printStandard() const {
    unsigned int h = (hour == 0 || hour == 12) ? 12 : hour % 12;
    std::cout << h << ":"
              << (minute < 10 ? "0" : "") << minute << ":"
              << (second < 10 ? "0" : "") << second
              << (hour < 12 ? " AM" : " PM") << "\n";
}

int main() {
    const Time sunset; // Đối tượng const
    // Gọi hợp lệ vì printUniversal là hàm const
    sunset.printUniversal();
    sunset.printStandard();

    // Đối tượng thông thường gọi hàm thay đổi dữ liệu
    Time meeting;
    meeting.setTime(15, 30, 0);
    meeting.printStandard();

    return 0;
}

#include <iostream>
#include <iomanip>
#include <stdexcept>

// Mô phỏng tệp tiêu đề Time.h
class Time {
public:
    // Nạp chồng constructor: constructor mặc định và constructor có tham số
    Time();
    Time(int h, int m, int s);

    void printUniversal() const;

private:
    unsigned int hour;
    unsigned int minute;
    unsigned int second;
};

// Triển khai sử dụng toán tử phân giải phạm vi :: và member initializer list
Time::Time()
    : hour(0), minute(0), second(0) {
    // Thân hàm rỗng vì toàn bộ thành viên đã được khởi tạo qua danh sách
}

Time::Time(int h, int m, int s)
    : hour(0), minute(0), second(0) {
    if (h >= 0 && h < 24 && m >= 0 && m < 60 && s >= 0 && s < 60) {
        hour = static_cast<unsigned int>(h);
        minute = static_cast<unsigned int>(m);
        second = static_cast<unsigned int>(s);
    } else {
        throw std::invalid_argument("hour, minute and/or second was out of range");
    }
}

void Time::printUniversal() const {
    std::cout << std::setfill('0')
              << std::setw(2) << hour << ":"
              << std::setw(2) << minute << ":"
              << std::setw(2) << second << "\n";
}

int main() {
    // Khởi tạo thông qua constructor mặc định
    Time t1;
    std::cout << "Default time: ";
    t1.printUniversal();

    // Khởi tạo thông qua constructor nạp chồng có tham số
    Time t2(11, 45, 30);
    std::cout << "Overloaded time: ";
    t2.printUniversal();

    return 0;
}
